honda-75	CB Hornet 2.0	MOTORCYCLES	469900	https://honda.com.np/wp-content/uploads/product-catalog/motorcycles/16-2.png	\N	{"usp": [{"body": "A veracious manifestation of style, safety, and power, Hornet 2.0 is all about riding against the wind, limitless. It’s a ride diligently crafted to perfection to serve all your wildest adventures. With a vigorous 184.4CC air-cooled BSVI HET engine that produces the fiercest power, this aggressive machine is here to turn heads with its sheer exhilaration and growl.\\r\\n\\r\\nNow, ride endless, fearless, and boundless, in sync with the wind in the all-new Hornet 2.0.\\r\\n<p style=\\\\\\"text-align: justify; font-size: 12px;\\\\\\"><i>*Disclaimer: All images are for illustration purposes </i></p>", "title": "Honda Hornet 2.0"}, {"body": "", "title": ""}], "engine": {"offer": "", "offer_page_link": "", "product_page_link": "/motorcycle/hornet-2-0/"}, "features": [{"image": "/wp-content/uploads/product-catalog/motorcycles/Aggressive_Tank_Design1.png", "title": "Aggressive Tank Design", "description": "Hornet 2.0 comes in a forward-leaning design and a bulky tank that represents the expression of dominance and aggression."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/LED_All_Around1.png", "title": "LED All-Around", "description": "Emphasizing its street-fighter-themed, aggressive look with a raging headlamp design, Hornet comes with LED lights all-around. The X-shape tail lamp and the newly designed winkers further add to its aggressive appearance."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Sporty_Split_Seat1.png", "title": "Sporty Split Seat", "description": "The sporty split seat in this machine takes its whole aggressive appeal to another level."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/FullyDigital_Liquid_Crystal_Meter1.png", "title": " Fully Digital, Liquid Crystal Meter", "description": "The fully digital meter in Hornet 2.0 lets you know exactly how much in sync with the wind you are, showing your info clearly with the 5-level Illumination Control on the crystal meter. Also, with the Gear Position Indicator, Battery Voltmeter, and Service Due Indicator, stay above the rest."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Golden_Upside_Down_Front_fork1.png", "title": "Golden Upside Down (USD) Front fork", "description": "With the first-in-segment golden upside-down suspension and superior & advanced suspension, every ride becomes a top-notch adventure."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Mono.jpeg.jpg", "title": "Mono Shock Rear Suspension", "description": "The mono-shock suspension helps increase stability and gives superior handling as you race while matching the speed of the wind. "}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Torque_Full_New_HET_Engine1.png", "title": "Torque Full, New HET Engine", "description": "The all-new Honda Hornet 2.0 is equipped with a HET engine that produces fierce power. The best-in-class mid-range torque* and BSVI engine make sure that you ride in an eco-friendly manner.\\r\\n"}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Stress_Free_Riding_Posture1.png", "title": "Stress-Free Riding Posture", "description": "The comfortable riding posture in Hornet 2.0 is ideal for both the street and the highway."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Mono_Shock_Rear_Suspension1.png", "title": "", "description": ""}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Key_On_Tank1.png", "title": "Key On Tank", "description": "It is a convenience enjoyed by the top bikes and a new special addition to our Honda Hornet 2.0."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Engine_Stop_Switch2.png", "title": "Engine Stop Switch", "description": "Conveniently turn off the engine in traffic without having to turn the key."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/1Channel_Front_ABS2.png", "title": "1 Channel, Front ABS", "description": "The ABS gives you better control as you brake, especially on slippery surfaces. By preventing the wheel from locking, it keeps you safe as you ride in sync with the wind."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/1Channel_Front_ABS2.png", "title": "140 mm Wide Rear Tyre", "description": "With dual, petal disc brakes, you get the utmost sense of control as you race against the wind. The petal shaped discs help dissipate heat and maintain braking efficiency."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Hazard_Switch1.png", "title": " Hazard Switch", "description": "The flashing indicator lights help you feel safe during emergency stops & for low visibility conditions"}, {"image": "", "title": "", "description": ""}], "variants": [], "bannerImage": "https://honda.com.np/wp-content/uploads/product-catalog/motorcycles/hornet-banner.png", "galleryImages": [], "specifications": {"engine": {"bore": "61.0 mm", "stroke": "4 Stroke", "displacement": "184.40 cc", "max_net_power": "12.7 kW @ 8500 rpm", "max_net_torque": "16.1 N-m @ 6000 rpm ", "air_filter_type": "SI Engine, BS-VI", "fuel_efficiency": "-", "starting_method": "Self Start", "compression_ratio": "9.5:1", "fuel_tank_capacity": "12 L"}, "electricals": {"meter": "", "battery": "12V, 5.0 Ah", "charging": "", "head_lamp": "LED"}, "transmission": {"type": "Multiplate Wet Clutch", "max_speed": "-", "no_of_gears": "5", "gear_pattern": "1-N-2-3-4-5"}, "tyres_brakes": {"tyre_size_rear": "140/70- 17", "tyre_type_rear": "140/70- 17 M/C 66S (Tubeless)", "tyre_size_front": "110/70-17 ", "tyre_type_front": "M/C 54S(Tubeless)", "brake_type_size_rear": "Disc - 220 mm", "brake_type_size_front": "Disc - 276 mm (1 Channel ABS)"}, "body_dimensions": {"width": "783 mm", "height": "1064 mm", "length": "2047 mm", "wheelbase": "1355 mm", "kerb_weight": "142 Kg", "ground_clearance": "167 mm"}, "frame_suspensions": {"frame_type": "Diamond Type", "rear_suspension": "Monoshock", "front_suspension": "Upside down Fork (USD)"}}}	2026-08-16 04:11:41.135	2026-08-16 04:11:53.369
honda-91	Honda NX 200	MOTORCYCLES	489900	https://honda.com.np/wp-content/uploads/product-catalog/motorcycles/2-8.png	\N	{"usp": [{"body": "<span style=\\\\\\"font-weight: 400;\\\\\\">Welcome to the world of exhilarating adventures and boundless possibilities with the Honda NX 200. Designed to ignite your passion for exploration, this dynamic motorcycle is engineered to conquer both urban streets and rugged terrains with ease. Whether you\\\\'re navigating through city traffic or embarking on a thrilling off-road journey, the NX 200 delivers an unmatched riding experience that redefines versatility and performance.</span><span style=\\\\\\"font-weight: 400;\\\\\\">\\r\\n</span><span style=\\\\\\"font-weight: 400;\\\\\\">\\r\\n</span>\\r\\n\\r\\n*<strong>Disclaimer</strong>: <span style=\\\\\\"font-weight: 400;\\\\\\">All images are for illustration purposes only. The actual product may vary from the shown image</span>\\r\\n\\r\\n&nbsp;", "title": "Power Through Boundaries"}, {"body": "", "title": ""}], "engine": {"offer": "", "offer_page_link": "", "product_page_link": "/motorcycle/honda-nx-200/"}, "features": [{"image": "/wp-content/uploads/2024/03/Untitled-5.png", "title": "URBAN-EXPLORER DESIGN", "description": "The Urban-Explorer Design, with the Tall Wind Visor ensures an ideal aerodynamics and a very comfortable ride."}, {"image": "/wp-content/uploads/2024/03/Untitled-6.png", "title": "UNDER COWL", "description": "The Under Cowl on this machine subtly completes the bike\\\\'s overall look, creating an irresistible appeal. It also lends to the aerodynamics of the bike to deliver a smooth ride.\\r\\n"}, {"image": "/wp-content/uploads/2024/03/Untitled-8.png", "title": "UPSWEPT EXHAUST", "description": "Carry a mean look when you go off course or take a detour. The Upswept Exhaust is undoubtedly a part of the paraphernalia of advanced biking.\\r\\n"}, {"image": "", "title": "", "description": ""}, {"image": "/wp-content/uploads/2024/03/Untitled-17.png", "title": "SPLIT STEP SEAT", "description": "The long and comfortable Split Step Seat is a stunner when the bike is parked. However, once you sit on it, it will give you and the pillion rider a new meaning to long rides"}, {"image": "/wp-content/uploads/2024/03/Untitled-4.png", "title": "DIAMOND TYPE STEEL FRAME", "description": "A city explorer needs a frame as strong as your will. The Diamond Type Steel Frame on the NX 200 is a testament of strength. A backbone behind your passion for biking.\\r\\n"}, {"image": "/wp-content/uploads/2024/03/Untitled-18.png", "title": "UPRIGHT RIDING POSITION", "description": "The NX 200 enables the rider to sit back, relax and enjoy a comfortable ride with the Upright Riding Position. It is especially useful for long rides, making sure the rider does not get fatigued along the way"}, {"image": "/wp-content/uploads/2024/03/Untitled-16.png", "title": "ALL-LED LIGHTING", "description": "The All-LED Lighting not only ensures visibility in every condition but also complements the contours of the machine that takes you places.\\r\\n"}, {"image": "/wp-content/uploads/2024/03/Untitled-15.png", "title": "KNUCKLE COVERS WITH LED WINKERS", "description": "The Winkers are ergonomically incorporated on the Knuckle Covers to ensure safety while letting you retain the style quotient. Look good while you conquer new paths.\\r\\n"}, {"image": "/wp-content/uploads/2024/03/Untitled-10.png", "title": "GOLDEN UPSIDE-DOWN (USD) FRONT FORK", "description": "This is a perfect example of style meets purpose. The Golden Front Fork will dazzle onlookers as you take your NX 200 for a spin in the city streets and also when you head away.\\r\\n"}, {"image": "/wp-content/uploads/2024/03/Untitled-2.png", "title": "ENGINE STOP SWITCH", "description": "The need to turn the key on and off at traffic lights no longer exists. Just flip the switch and continue on your adventure without any impediment\\r\\n"}, {"image": "/wp-content/uploads/2024/03/Untitled-1.png", "title": "HAZARD SWITCH", "description": "Should you need to make a stop or slow down unexpectedly, the Hazard Switch will keep you safe by making people notice you on the road\\r\\n"}, {"image": "/wp-content/uploads/2024/03/Untitled-11.png", "title": "MONO SHOCK REAR SUSPENSION", "description": "You need to always maintain a good center of gravity as you take your bike on the courses less traveled. The Mono Shock Rear Suspension will make sure your every ride is worth it while it handles the bumps for you"}, {"image": "/wp-content/uploads/2024/03/Untitled-14.png", "title": " RAISED AND SWAGED HANDLEBAR", "description": "Inspired by high-end machines, the Raised and Swaged Handlebar lends a look of ruggedness to the design, with the increased wall thickness adding to the strength of the vehicle.\\r\\n"}, {"image": "/wp-content/uploads/2024/03/Untitled-5.png", "title": "DYNAMIC PERFORMANCE", "description": "This masterpiece of an engine has passed many tests to enable you to plan the ideal commute, the perfect getaway and take your bike off course. With superior fuel-efficiency, the PGM-Fi engine produces power that lets you get away from the mundane and see the other side of life"}], "variants": [], "bannerImage": "https://honda.com.np/wp-content/uploads/product-catalog/motorcycles/CB-200-X-copy.png", "galleryImages": [], "specifications": {"engine": {"bore": "61.0 ", "stroke": "x63.096", "displacement": "184.4 cc", "max_net_power": "12.7kW @ 8500 rpm", "max_net_torque": " 16.1 N-m @ 6000 rpm", "air_filter_type": "x 63.096", "fuel_efficiency": "-", "starting_method": "self", "compression_ratio": "9.5:1", "fuel_tank_capacity": "12 L"}, "electricals": {"battery": " 12V, 5,0 Ah", "head_lamp": "LED"}, "transmission": {"type": " Multi Plate Wet Clutch", "max_speed": "-", "no_of_gears": "5", "gear_pattern": "-"}, "tyres_brakes": {"tyre_size_rear": " 140/70-17 M/C 66S ", "tyre_type_rear": "Tubeless", "tyre_size_front": "110/70-17 M/C 54S ", "tyre_type_front": "Tubeless", "brake_type_size_rear": "Disc 220 mm", "brake_type_size_front": " Disc 276 mm"}, "body_dimensions": {"width": "843 mm", "height": "1248 mm", "length": "2035 mm", "wheelbase": "1355 mm", "kerb_weight": "147 kg", "ground_clearance": "167 mm"}, "frame_suspensions": {"frame_type": "Diamond Type", "rear_suspension": "Monoshock", "front_suspension": "Upside Down Front Fork (USD)"}}}	2026-08-16 04:11:41.15	2026-08-16 04:11:53.38
honda-94	Honda Shine BS6	MOTORCYCLES	305900	https://honda.com.np/wp-content/uploads/product-catalog/motorcycles/DSC_9543-copy-3_12_11zon-scaled.jpg	\N	{"usp": [{"body": "<span style=\\\\\\"font-weight: 400;\\\\\\">Step up your ride with the Honda Shine BS6 – the ultimate blend of sophistication, comfort, and top-notch performance. Designed for those who demand the best, this bike guarantees a smooth and eco-friendly ride every time you hit the road.</span>\\r\\n\\r\\n<span style=\\\\\\"font-weight: 400;\\\\\\">\\r\\n</span><em><span style=\\\\\\"font-weight: 400;\\\\\\">*Disclaimer: All images are for illustration purposes only. Actual product may vary from the shown image.</span></em>", "title": "The Ultimate Upgrade"}, {"body": "", "title": ""}], "engine": {"offer": "", "offer_page_link": "", "product_page_link": "/motorcycle/honda-shine-bs6/"}, "features": [{"image": "/wp-content/uploads/product-catalog/motorcycles/ALL-NEW-METER-DESIGN.png", "title": "All New Meter Design", "description": "Features a refreshed meter design that maintains simplicity and sophistication, now including a Side Stand Indicator with Engine Cut Off for added safety, indicating when the stand is down."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/SLID-ENGINE-CUT-OFF.png", "title": "Side Stand Engine Cut-Off", "description": "Enhances rider safety by automatically cutting off the ignition if the bike is put in gear with the side stand engaged.\\r\\n"}, {"image": "/wp-content/uploads/product-catalog/motorcycles/ACG-Start.png", "title": "Silent Start with ACG", "description": "Honda\\\\'s ACG starter eliminates gear meshing noise for smooth engine starts without jerks.\\r\\n"}, {"image": "/wp-content/uploads/product-catalog/motorcycles/5-SPEED-TRANSMISSION.png", "title": "5-Speed Transmission", "description": "Enjoy a seamless and comfortable riding experience with the 5-speed transmission.\\r\\n"}, {"image": "/wp-content/uploads/product-catalog/motorcycles/DC-HEADLAMP.png", "title": "DC Headlamp", "description": "Provides consistent illumination regardless of speed or riding conditions, ensuring clear visibility at all times"}, {"image": "/wp-content/uploads/product-catalog/motorcycles/ENGINE-START-STOP-SWITCH-1.png", "title": "Engine Start/Stop Switch", "description": "Offers convenience with the ability to start and stop the bike with a simple switch, enhancing usability.\\r\\n"}, {"image": "/wp-content/uploads/product-catalog/motorcycles/More-Seating-Space-and-easy-ground-touch.png", "title": "More Seating Space & Easy Ground Touch", "description": "A longer 651 mm seat provides ample comfort for both rider and pillion, while smooth integration with the tank improves ground touch."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/INTEGRATED-HEADLAMP-BEAM-PASSING-SWITCH.png", "title": "Integrated Headlamp Beam & Passing Switch", "description": "Smart single switch for easy control of passing signal and low/high beams."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/More-Ground-Clearance.png", "title": "More Ground Clearance & Wheelbase", "description": "162 mm ground clearance ensures confidence over rough roads, while the 1285 mm wheelbase enhances stability at higher speeds."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/BOLD-FRONT-VISOR.png", "title": "Bold Front Visor ", "description": "Front Visor with newly designed chrome garnish gives a completely new look to the front cowl and brings out its bold character. \\r\\n"}, {"image": "/wp-content/uploads/product-catalog/motorcycles/PREMIUM-CHROME-STROKE-ON-SIDE-COVER.png", "title": "Premium Chrome Stroke On Side Cover ", "description": "The premium chrome stroke on side cover gives the new Shine an elegant stance to make it stand out in a crowd.\\r\\n"}], "variants": [{"name": "SHINE 125 DSS BSVI", "image": "https://honda.com.np/wp-content/uploads/product-catalog/motorcycles/Shine-BS6-DSS_11zon.png", "price": 305900, "colorCode": ""}, {"name": "SHINE 125 DRS BSVI", "image": "https://honda.com.np/wp-content/uploads/product-catalog/motorcycles/Shine-BS6-DRS_11zon.png", "price": 294900, "colorCode": ""}], "bannerImage": "https://honda.com.np/wp-content/uploads/product-catalog/motorcycles/Honda-Shine-BS6-Web-Banner.png", "galleryImages": [], "specifications": {"engine": {"bore": "50 mm", "stroke": "63.121 mm", "displacement": "123.94 cc", "max_net_power": "7.9 kW @ 7500 rpm", "max_net_torque": "11 N-m @ 6000 rpm", "air_filter_type": "-", "fuel_efficiency": "-", "starting_method": "Self/Kick", "compression_ratio": "10.0:1", "fuel_tank_capacity": "10.5L"}, "electricals": {"meter": "", "battery": " 12 V, 4.0 Ah", "charging": "", "head_lamp": "Halogen Bulb, DC"}, "transmission": {"type": "Multiplate Wet Clutch", "max_speed": "-", "no_of_gears": "5 Gears", "gear_pattern": "-"}, "tyres_brakes": {"tyre_size_rear": " 80/100-18 M/C 54P", "tyre_type_rear": "Tubeless", "tyre_size_front": "80/100-18 M/C 47P", "tyre_type_front": "Tubeless", "brake_type_size_rear": "Drum-130 mm", "brake_type_size_front": " Disc-240 mm, Drum-130 mm"}, "body_dimensions": {"width": "737 mm", "height": "1116 mm", "length": "2046 mm", "wheelbase": "1285 mm", "kerb_weight": "113 kg", "ground_clearance": "162 mm"}, "frame_suspensions": {"frame_type": " Diamond Type", "rear_suspension": "Hydraulic Type", "front_suspension": "Telescopic"}}}	2026-08-16 04:11:41.16	2026-08-16 04:11:53.385
