honda-88	Honda SP Shine 125	MOTORCYCLES	306900	https://honda.com.np/wp-content/uploads/product-catalog/motorcycles/1-5.png	\N	{"usp": [{"body": "The Honda SP 125 is the most premium 125cc bike which comes loaded with many modern features such as an LED headlight, fully-digital instrument cluster, side-stand engine cut off and a silent starter. Advanced traction with wider rear tyre ensures safety with better braking. Advanced looks and advanced display keeps you ahead while making sure you grab some glances.\\r\\n\\r\\n*Disclaimer: All images are for illustration purposes only. Actual product may vary from the shown image.", "title": " Thrill of an advanced ride"}, {"body": "", "title": ""}], "engine": {"offer": "", "offer_page_link": "", "product_page_link": "/motorcycle/shine-sp-125-bs6/"}, "features": [{"image": "/wp-content/uploads/product-catalog/motorcycles/Silent_Start_With_Acg_dev_four.png", "title": "SILENT START WITH ACG", "description": "The unique ACG starter motor removes gear meshing noise and helps start the engine without a jolt. Effortless ignition, silent start."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/125cc_Bs-Vi_Engine_dev_four.png", "title": " 125CC BS-VI ENGINE", "description": "The engines most recent advancement is revolutionary. The intelligent engine offers unparalleled performance and helps to maintain a cleaner atmosphere.\\r\\n"}, {"image": "/wp-content/uploads/product-catalog/motorcycles/esp_dev_four.png", "title": "eSP", "description": "The engines most recent advancement is revolutionary. The intelligent engine offers unparalleled performance and helps to maintain a cleaner atmosphere."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Friction_Reduction_dev_four.png", "title": " FRICTION REDUCTION", "description": "The piston cooling jet reduces friction and maintains optimum engine temperature. The offset cylinder and rocker roller arm further reduces the frictional losses in the engine.\\r\\n"}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Full_Digital_Meter_dev_four.png", "title": " FULL DIGITAL METER", "description": "The full digital meter displays real-time mileage, average mileage, distance to empty, service due indicator, gear position indicator & eco indicator. It also includes the side stand indicator with engine cut-off that adds to the safety of the rider."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Side_stand_dev_four.png", "title": "SIDE STAND ENGINE CUT-OFF", "description": "With a smart inbuilt system, SP 125 cuts off the engine when the side stand is engaged."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Wider_Rear_tyre_dev_four.png", "title": "WIDER REAR TYRE", "description": "SP125 comes with a wider rear tyre which ensures better braking by giving better traction and grip.\\r\\n"}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Bold_Rear_Stance_With_Tail_Lamp_dev_four.png", "title": "BOLD REAR STANCE WITH TAIL LAMP", "description": "The bold rear stance with the tail lamp matches with the body, enhancing the design statement."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Dynamic_Tank_Design_With_Edgy_Graphics_dev_four.png", "title": "DYNAMIC TANK DESIGN WITH EDGY GRAPHICS", "description": "The muscular fuel tank design with new edgy graphics enhances the already bold looks of SP 125."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Premium_Chrome_Muffler_Cover_dev_four.png", "title": "PREMIUM CHROME MUFFLER COVER", "description": "The stylish chrome muffler enhances the sporty looks to a more premium style."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Sharp_Led_Dc_Headlamp_dev_four.png", "title": " SHARP LED DC HEADLAMP", "description": "The sharp LED DC headlamp gives consistent illumination while riding in any speed and riding conditions."}, {"image": "/wp-content/uploads/product-catalog/motorcycles/Sporty_Split_Alloy_Wheels_dev_four.png